create table public.performance_snapshots(id uuid primary key default gen_random_uuid(),portfolio_id uuid not null references public.paper_portfolios(id),policy_version text not null,model_version text not null,information_cutoff_at timestamptz not null,input_hash text not null unique,funnel jsonb not null,rates jsonb not null,reject_reasons jsonb not null,blockers jsonb not null,coverage jsonb not null,metrics jsonb not null,limitations jsonb not null default'[]',created_at timestamptz not null default now());create or replace function public.prevent_performance_snapshot_mutation()returns trigger language plpgsql as $$begin raise exception'Performance snapshots are immutable';end$$;create trigger performance_snapshots_immutable before update or delete on public.performance_snapshots for each row execute function public.prevent_performance_snapshot_mutation();alter table public.performance_snapshots enable row level security;create policy "public read system performance" on public.performance_snapshots for select using(exists(select 1 from public.paper_portfolios p where p.id=portfolio_id and p.portfolio_scope='SYSTEM_RESEARCH'));grant select on public.performance_snapshots to anon,authenticated;grant all on public.performance_snapshots to service_role;alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance'));
